    {
      "subject": "English cue and sense",
      "conclusion": "“School fee” and the sense “money charged for attending school” are accurate, though “school fees” is often the more natural English plural.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.usaid.gov/sites/default/files/2023-10/PA00KRBN.pdf"
      ]
    },
    {
      "subject": "Indonesian answer: biaya sekolah",
      "conclusion": "Correct and ordinary Indonesian. KBBI defines biaya as money expended for something and gives biaya sekolah as an example; Indonesian school-fee materials also use Biaya Sekolah.",
      "material_risk": false,
      "evidence_refs": [
        "https://kbbi.web.id/biaya.html",
        "https://id.jisedu.or.id/admissions/fees"
      ]
    },
    {
      "subject": "Indonesian competing equivalent: uang sekolah",
      "conclusion": "A valid everyday Indonesian alternative meaning school fees, but its existence does not make biaya sekolah unsuitable or erase the national lexical preference represented here.",
      "material_risk": false,
      "evidence_refs": [
        "https://kamuslengkap.id/kamus/kbbi/arti-kata/uang-sekolah/",
        "https://elon.io/learn-hardcore-indonesian/lexicon/584695/orang-tua-saya-membayar-biaya-sekolah-setiap-bulan"
      ]
    },
    {
      "subject": "Malaysian answer: yuran sekolah",
      "conclusion": "Correct and ordinary Malaysian Malay. Malaysian government and school materials use yuran for education-related fees, including yuran sekolah and yuran pengajian.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.dosm.gov.my/uploads/census-surveys/guideline-20250324130228_1.pdf",
        "https://www.moe.gov.my/storage/files/shares/pekeliling_dan_garis_panduan/pendidikan_swasta/GP%20Pusat%20Perkembangan%20Latest.pdf",
        "https://www.wadisofia.edu.my/fees.php?lang=ms"
      ]
    },
